#!/usr/bin/env bash
# generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
#
# Start (or restart) the local Nextcloud dev instance and enable the UPM app.
#
# Usage:
#   scripts/start-nextcloud.sh              # start, wait for install, enable UPM
#   scripts/start-nextcloud.sh --reset      # wipe the dev volume, then start fresh
#   scripts/start-nextcloud.sh --no-app     # start Nextcloud only
#   scripts/start-nextcloud.sh --logs       # follow the container logs afterwards
#   scripts/start-nextcloud.sh --stop       # stop the instance
#
# Notes:
#   * The compose file is generated into .dev/ and mounts this repository at
#     /var/www/html/custom_apps/upm, so frontend edits are picked up after
#     `npm run build` and a browser reload.
#   * The official image's config/apps.config.php marks custom_apps as the only
#     writable app root. The bind mount makes that directory non-empty before
#     the entrypoint can chown it, which breaks the first install with
#     'Cannot write into "apps" directory'. A one-off root container fixes the
#     ownership before Nextcloud starts.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(dirname "$SCRIPT_DIR")"
DEV_DIR="$PROJECT_ROOT/.dev"
COMPOSE_FILE="$DEV_DIR/docker-compose.nextcloud.yml"
PORT="${UPM_NEXTCLOUD_PORT:-8080}"

RESET=0
NO_APP=0
FOLLOW=0
STOP=0

die() { echo "error: $*" >&2; exit 1; }

while [ $# -gt 0 ]; do
	case "$1" in
		--reset) RESET=1 ;;
		--no-app) NO_APP=1 ;;
		--logs) FOLLOW=1 ;;
		--stop) STOP=1 ;;
		-h|--help)
			sed -n '4,21p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'
			exit 0
			;;
		*) die "unknown option: $1 (try --help)" ;;
	esac
	shift
done

command -v docker >/dev/null 2>&1 || die "docker is not installed"
docker compose version >/dev/null 2>&1 || die "docker compose is not available"

compose() { docker compose -f "$COMPOSE_FILE" "$@"; }
occ() { compose exec -T -u www-data nextcloud php occ "$@"; }

if [ "$STOP" = 1 ]; then
	[ -f "$COMPOSE_FILE" ] || die "no compose file at $COMPOSE_FILE"
	compose down --remove-orphans
	echo "Nextcloud stopped (the data volume is kept; use --reset to delete it)."
	exit 0
fi

mkdir -p "$DEV_DIR"

# Regenerated on every run so the mount always points at this checkout.
cat > "$COMPOSE_FILE" <<YAML
# generated by scripts/start-nextcloud.sh - do not edit, rerun the script instead
services:
  nextcloud:
    image: nextcloud:28-apache
    ports:
      - "${PORT}:80"
    environment:
      SQLITE_DATABASE: upm
      NEXTCLOUD_ADMIN_USER: admin
      NEXTCLOUD_ADMIN_PASSWORD: admin
    volumes:
      - nextcloud-data:/var/www/html
      - ${PROJECT_ROOT}:/var/www/html/custom_apps/upm
volumes:
  nextcloud-data:
YAML

if [ "$RESET" = 1 ]; then
	echo "==> Removing the dev instance and its data volume"
	compose down -v --remove-orphans
fi

echo "==> Preparing the apps directory"
compose run --rm --no-deps -u root --entrypoint sh nextcloud -c \
	'mkdir -p /var/www/html/custom_apps && chown www-data:www-data /var/www/html/custom_apps'

echo "==> Starting Nextcloud"
compose up -d

echo "==> Waiting for Nextcloud to finish installing (first run takes ~1 min)"
installed=0
for _ in $(seq 1 100); do
	if occ status --output=json 2>/dev/null | grep -q '"installed":true'; then
		installed=1
		break
	fi
	sleep 3
done

if [ "$installed" != 1 ]; then
	echo "error: Nextcloud did not finish installing" >&2
	compose logs --tail=40 nextcloud >&2 || true
	echo "hint: rerun with --reset to recreate the dev volume" >&2
	exit 1
fi

if [ "$NO_APP" != 1 ]; then
	echo "==> Enabling the UPM app"
	occ app:enable upm
	occ app:list | grep -q 'upm' || die "the upm app is not listed after enabling"
fi

echo ""
echo "Nextcloud: http://localhost:$PORT/            (admin / admin)"
echo "UPM:       http://localhost:$PORT/index.php/apps/upm/"
echo "Database:  <user files>/upm/upm.db"
echo ""
echo "Rebuild after frontend changes: npm run build"

if [ "$FOLLOW" = 1 ]; then
	compose logs -f nextcloud
fi
